    },
    {
      "name": "虚拟输入设备",
      "description": "通过 Linux uinput 子系统创建和管理虚拟输入设备，可从现有设备克隆或从零构造"
    }
  ],
  "domain": "系统库/输入子系统",
  "target_users": "X.Org/Wayland 显示服务器开发者、输入驱动开发者、libinput 库使用者、桌面环境与合成器开发者"
}
